/* SAFA · ASYS 245 offline service worker. GENERATED by assets/build-sw.py from assets/sw.template.js — edit the template, not sw.js.
   Pages: network first (students online always see the newest class), saved copy when offline or the network is slow.
   CSS, JS, images, fonts: saved copy first, refreshed in the background. */
const VERSION = '__VERSION__';
const CACHE = 'asys245-' + VERSION;
const RUNTIME = 'asys245-runtime';
const PRECACHE = __PRECACHE__;
const SCOPE = self.registration.scope;
const NET_TIMEOUT_MS = 3500;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c =>
    Promise.all(PRECACHE.map(u => c.add(new Request(u, { cache: 'reload' })).catch(() => null)))
  ).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(
    keys.filter(k => k.startsWith('asys245-') && k !== CACHE && k !== RUNTIME).map(k => caches.delete(k))
  )).then(() => self.clients.claim()));
});

function fromCache(req) {
  return caches.match(req, { ignoreSearch: true }).then(r => {
    if (r) return r;
    const u = new URL(req.url);
    if (u.pathname.endsWith('/')) return caches.match(u.origin + u.pathname + 'index.html');
    if (u.pathname.endsWith('/index.html')) return caches.match(u.origin + u.pathname.slice(0, -10));
    return undefined;
  });
}

function networkFirst(req) {
  return new Promise(resolve => {
    let done = false;
    const fallback = () => fromCache(req).then(r => r || Response.redirect(SCOPE + 'offline.html', 302));
    const timer = setTimeout(() => { fromCache(req).then(r => { if (r && !done) { done = true; resolve(r); } }); }, NET_TIMEOUT_MS);
    fetch(req).then(res => {
      if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      if (!done) { done = true; clearTimeout(timer); resolve(res); }
    }).catch(() => { if (!done) { done = true; clearTimeout(timer); resolve(fallback()); } });
  });
}

function staleWhileRevalidate(req, cacheName) {
  return caches.open(cacheName).then(c => c.match(req, { ignoreSearch: true }).then(hit => {
    const net = fetch(req).then(res => {
      if (res && (res.ok || res.type === 'opaque')) c.put(req, res.clone());
      return res;
    }).catch(() => hit);
    return hit || net;
  }));
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    if (!req.url.startsWith(SCOPE)) return;
    if (req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html')) { e.respondWith(networkFirst(req)); return; }
    const precached = PRECACHE.some(p => new URL(p, SCOPE).href === url.origin + url.pathname);
    e.respondWith(staleWhileRevalidate(req, precached ? CACHE : RUNTIME));
    return;
  }
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    e.respondWith(staleWhileRevalidate(req, RUNTIME));
  }
});
